// Deferred Register Example
private static final DeferredRegister<Block> BLOCKS = DeferredRegister.create(ForgeRegistries.BLOCKS, MODID);
private static final DeferredRegister<Item> ITEMS = DeferredRegister.create(ForgeRegistries.ITEMS, MODID);

// Register blocks and items
public static final RegistryObject<Block> MY_BLOCK = BLOCKS.register("my_block", () -> new Block(Block.Properties.create(Material.STONE)));
public static final RegistryObject<Item> MY_BLOCK_ITEM = ITEMS.register("my_block", () -> new BlockItem(MY_BLOCK.get(), new Item.Properties()));

// Register in constructor
public MyMod() {
    BLOCKS.register(FMLJavaModLoadingContext.get().getModEventBus());
    ITEMS.register(FMLJavaModLoadingContext.get().getModEventBus());
}
